package org.jlinalg.genetics;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.zip.GZIPOutputStream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class SpliceAiVcfTest {
    @TempDir Path temporary;
    private static final String HEADER="##fileformat=VCFv4.2\n##INFO=<ID=SpliceAI,Number=.,Type=String,Description=\"SpliceAIv1.3 variant annotation. Format: ALLELE|SYMBOL|DS_AG|DS_AL|DS_DG|DS_DL|DP_AG|DP_AL|DP_DG|DP_DL\">\n#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\tFORMAT\tα sample\n";
    private static final String A="C|GENE1|-0.25|0.25|0.10|-0.10|0|0|0|0",MISSING="C|GENE1|.|.|.|.|.|.|.|.",ZERO="G|GENE2|0.00|0.00|0.00|0.00|-2|3|-1|0";
    private Path write(String text)throws IOException{Path p=temporary.resolve(UUID.randomUUID()+".vcf");Files.writeString(p,text,StandardCharsets.UTF_8);return p;}
    private String text(String annotation){return HEADER+"1\t10\tliteral-id\tA\tC,G\t.\tPASS\tK=NaN;SpliceAI="+annotation+"\tGT:DS\t1|2:0.2000\n";}
    private SpliceAiVcf.Limits limits(){return new SpliceAiVcf.Limits(1000000,1000,10000,10000);}
    private SpliceAiVcf.Summary inspect(Path path,List<SpliceAiVcf.Annotation> a,List<SpliceAiVcf.Allele> b,List<SpliceAiVcf.Gene> g)throws IOException{return SpliceAiVcf.inspect(path,limits(),s->{},v->{},a::add,b::add,g::add);}
    @Test void everyAlleleAndDuplicateGeneContextSurvives()throws Exception{var a=new ArrayList<SpliceAiVcf.Annotation>();var b=new ArrayList<SpliceAiVcf.Allele>();var g=new ArrayList<SpliceAiVcf.Gene>();var s=inspect(write(text(A+","+MISSING+","+ZERO)),a,b,g);assertEquals(1,s.variants());assertEquals(2,s.alternateAlleles());assertEquals(3,s.annotations());assertEquals(2,s.geneGroups());assertEquals(2,g.get(0).annotations());assertEquals(List.of(1,2),g.get(0).annotationIndexes());assertEquals(1,b.get(0).fullyScoredAnnotations());assertEquals(1,b.get(0).missingScoreAnnotations());assertEquals("0.25",b.get(0).maximumObservedScore());assertEquals("-0.25",b.get(0).minimumObservedScore());assertEquals("0.00",b.get(1).maximumObservedScore());assertEquals(List.of("GENE1"),b.get(0).genes());}
    @Test void nonfiniteScoresAreRetainedAsUnassessableAndNeverBecomeZero()throws Exception{var a=new ArrayList<SpliceAiVcf.Annotation>();var b=new ArrayList<SpliceAiVcf.Allele>();var s=inspect(write(text("C|GENE1|NaN|Inf|-Inf|.|0|0|0|0")),a,b,new ArrayList<>());assertEquals(1,s.nonfiniteScoreAnnotations());assertEquals(1,s.missingScoreAnnotations());assertEquals(1,s.unannotatedAlleles());assertEquals("NONFINITE_SCORES_UNASSESSABLE",a.get(0).state());assertNull(b.get(0).maximumObservedScore());assertNull(b.get(1).maximumObservedScore());assertEquals("NaN",a.get(0).fields().get(2));}
    @Test void sourceNegativeScoresAndSignedZeroAreNotClippedOrReformatted()throws Exception{var a=new ArrayList<SpliceAiVcf.Annotation>();inspect(write(text("C|GENE1|-0.00|0.00|-0.10|0.00|0|0|0|0")),a,new ArrayList<>(),new ArrayList<>());assertEquals("-0.00",a.get(0).maximumObservedScore());assertEquals("-0.10",a.get(0).minimumObservedScore());assertTrue(a.get(0).completeScores());}
    @Test void completeUnsupportedTupleDiffersFromPartialData()throws Exception{var s=inspect(write(text(MISSING)),new ArrayList<>(),new ArrayList<>(),new ArrayList<>());assertEquals(0,s.partialTuples());var partial=inspect(write(text("C|GENE1|.|0.10|.|.|.|.|.|.")),new ArrayList<>(),new ArrayList<>(),new ArrayList<>());assertEquals(1,partial.partialTuples());}
    @Test void absentAndDotAnnotationsRemainExplicitlyUnscored()throws Exception{for(String info:List.of(".","K=NaN","SpliceAI=.")){var b=new ArrayList<SpliceAiVcf.Allele>();Path p=write(text(A).replace("K=NaN;SpliceAI="+A,info));var s=inspect(p,new ArrayList<>(),b,new ArrayList<>());assertEquals(0,s.annotations());assertEquals(2,s.unannotatedAlleles());assertTrue(b.stream().allMatch(x->x.annotations()==0&&x.maximumObservedScore()==null));}}
    @Test void blankGeneRemainsUnassignedRatherThanInvented()throws Exception{var a=new ArrayList<SpliceAiVcf.Annotation>();var g=new ArrayList<SpliceAiVcf.Gene>();var s=inspect(write(text("C||0.01|0.02|0.03|0.04|0|1|2|3")),a,new ArrayList<>(),g);assertEquals(1,s.annotationsWithoutGene());assertEquals("",a.get(0).gene());assertTrue(g.isEmpty());}
    @Test void literalOriginalGenotypesAndSourceReserializationAreBothRetained()throws Exception{String original=text(A).replace(HEADER,HEADER.replace(HEADER.substring(HEADER.indexOf("##INFO"),HEADER.indexOf("#CHROM")),"")).replace("K=NaN;SpliceAI="+A,"K=NaN");String annotated=text(A).replace("1|2:0.2000","1|2:0.2");var v=new ArrayList<SpliceAiVcf.Variant>();var s=SpliceAiVcf.audit(write(original),write(annotated),limits(),x->{},v::add,x->{},x->{},x->{});assertTrue(s.originalInputAudited());assertEquals(1,s.sourceReserializedRows());assertEquals(List.of("α sample"),v.get(0).sourceReserializedColumns());assertEquals("1|2:0.2000",v.get(0).originalFields().get(9));assertEquals("1|2:0.2",v.get(0).annotatedFields().get(9));}
    @Test void changedIdentityAndSampleNamesCannotBeAdmitted()throws Exception{Path before=write(text(A));assertThrows(IOException.class,()->SpliceAiVcf.audit(before,write(text(A).replace("literal-id","other-id")),limits(),s->{},v->{},a->{},b->{},g->{}));assertThrows(IOException.class,()->SpliceAiVcf.audit(before,write(text(A).replace("α sample","other sample")),limits(),s->{},v->{},a->{},b->{},g->{}));}
    @Test void missingOrExtraSourceRowsCannotBeAdmitted()throws Exception{Path before=write(text(A));assertThrows(IOException.class,()->SpliceAiVcf.audit(before,write(HEADER),limits(),s->{},v->{},a->{},b->{},g->{}));String row=text(A).substring(HEADER.length());assertThrows(IOException.class,()->SpliceAiVcf.audit(before,write(text(A)+row),limits(),s->{},v->{},a->{},b->{},g->{}));}
    @Test void invalidFieldCountsAllelesAndPositionsFailWithoutRepair()throws Exception{for(String a:List.of("C|GENE1|0|0|0|0|0|0|0","C|GENE1|0|0|0|0|0|0|0|0|extra","T|GENE1|0|0|0|0|0|0|0|0","C|GENE1|x|0|0|0|0|0|0|0","C|GENE1|0|0|0|0|1.2|0|0|0","C|GENE1||0|0|0|0|0|0|0"))assertThrows(IOException.class,()->inspect(write(text(a)),new ArrayList<>(),new ArrayList<>(),new ArrayList<>()));}
    @Test void ambiguousRepeatedAlternateAndRepeatedInfoAreRefused()throws Exception{assertThrows(IOException.class,()->inspect(write(text(A).replace("\tC,G\t","\tC,C\t")),new ArrayList<>(),new ArrayList<>(),new ArrayList<>()));assertThrows(IOException.class,()->inspect(write(text(A).replace("K=NaN;SpliceAI=","SpliceAI="+A+";SpliceAI=")),new ArrayList<>(),new ArrayList<>(),new ArrayList<>()));}
    @Test void flagEmptyOrWrongSchemaIsNotAnUnannotatedSuccess()throws Exception{for(String t:List.of(text(A).replace("SpliceAI="+A,"SpliceAI"),text(A).replace("SpliceAI="+A,"SpliceAI="),text(A).replace("DS_AG|DS_AL","DS_AL|DS_AG")))assertThrows(IOException.class,()->inspect(write(t),new ArrayList<>(),new ArrayList<>(),new ArrayList<>()));}
    @Test void gzipAndLiteralUnicodeHaveTheSameScientificRecords()throws Exception{String t=text(A.replace("GENE1","Gene α"));Path p=temporary.resolve("complete.vcf.gz");try(var out=new GZIPOutputStream(Files.newOutputStream(p))){out.write(t.getBytes(StandardCharsets.UTF_8));}var a=new ArrayList<SpliceAiVcf.Annotation>();var b=new ArrayList<SpliceAiVcf.Annotation>();assertEquals(inspect(write(t),a,new ArrayList<>(),new ArrayList<>()),inspect(p,b,new ArrayList<>(),new ArrayList<>()));assertEquals(a,b);}
    @Test void rowAnnotationAndDecodedCapacitiesFailTheCompleteFile()throws Exception{Path p=write(text(A+","+A));assertThrows(IOException.class,()->SpliceAiVcf.inspect(p,new SpliceAiVcf.Limits(100000,1,1,10000),s->{},v->{},a->{},b->{},g->{}));assertThrows(IOException.class,()->SpliceAiVcf.inspect(p,new SpliceAiVcf.Limits(10,100,100,10000),s->{},v->{},a->{},b->{},g->{}));}
}
